import "mx-global";
import { Big } from "big.js";

// BEGIN EXTRA CODE
// END EXTRA CODE

/**
 * @param {string} widgetName
 * @param {string} paneName
 * @returns {Promise.<void>}
 */
export async function MaximizeSplitPane(widgetName, paneName) {
	// BEGIN USER CODE
	if (typeof $ === 'undefined') {
		await loadScript("./js/jquery-3.7.1.min.js");
	}
	if (typeof $ === 'undefined') {
		console.error("jQuery not available after loading.");
		return;
	}
	const Left_Maximized = "left-maximized";

	paneName = paneName.toLowerCase();

	const outerSplitter = $(".splitPane-Outer");
	const innerSplitter = $(".splitPane-Inner");

	const instructionPane = outerSplitter.find(".Pane1").first();
	const outerPane2 = outerSplitter.find(".Pane2").first();
	const taskWorkAreaPane = innerSplitter.find(".Pane1").first();
	const documentPane = innerSplitter.find(".Pane2").first();


	if (widgetName.toLowerCase() == "outersplitpanewidget") {
		if (paneName == "pane1") {
			showPane(instructionPane);
			instructionPane.removeClass("instructionPane");
			hidePane(outerPane2);
			showMinMaxSplitButtons("instruction_max");
		}
	}
	else {

		switch (paneName) {
			case "pane1":
				hidePane(instructionPane);
				instructionPane.removeAttr("visible");

				showPane(outerPane2);

				showMinMaxSplitButtons("taskworkarea_max");
				outerPane2.removeClass("taskworkarea-min-mode");
				outerPane2.addClass("taskworkarea-max-mode");
				break;
			case "docpane":
				showPane(taskWorkAreaPane);
				showPane(documentPane);
				innerSplitter.removeClass(Left_Maximized);
				showMinMaxSplitButtons("docpane_max");
				break;

			case "docpanefull":
				if (isPaneVisible(instructionPane)) {
					instructionPane.attr("visible", "true");
				}
				hidePane(instructionPane);
				hidePane(taskWorkAreaPane);

				showMinMaxSplitButtons("docpanefull_max");
				break;
		}
	}

	adjustDocumentCarousalWidgetWidth();

	// END USER CODE
}
